export const getHistoricalTier = (fighterName, eventDateStr) => {
  const entries = HISTORICAL_RANKINGS[fighterName];
  if (!entries || !entries.length) return 0.12;
  const s = eventDateStr.replace(/-/g, '');
  // Keys are YYYYMMDD integers; pad YYYY-MM dates to YYYYMM01 for safe comparison
  const eventYMD = parseInt(s.length >= 8 ? s.slice(0, 8) : s + '01');
  if (isNaN(eventYMD)) return 0.12;
  let lo = 0, hi = entries.length - 1, best = null;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (entries[mid][0] <= eventYMD) { best = entries[mid]; lo = mid + 1; }
    else hi = mid - 1;
  }
  if (!best) return 0.12;
  const rank = best[1];
  if (rank === 0) return 1.0;
  return Math.max(0.42, 0.93 * Math.exp(-0.037 * (rank - 1)));
};
